const body = $input.item.json.body || $input.item.json;
if (!body.id || !body.name) return [{ json: { skip: true, reason: 'missing id or name' } }];

return [{ json: {
  client_id:       body.id,
  name:            body.name,
  company:         body.company || body.name,
  email:           body.email   || null,
  phone:           body.phone   || null,
  document:        body.document || null,
  organization_id: body.organization_id,
  has_email:       !!body.email,
  skip:            false
}}];

const d = $input.item.json;

// Monta o JSON completo como string para enviar ao proxy
// Evita problemas de serialização do n8n com objetos aninhados
const proxyBody = JSON.stringify({
  method: 'POST',
  path: '/v3/customers',
  payload: {
    name:              d.company,
    cpfCnpj:           d.document,
    email:             d.email,
    phone:             d.phone,
    externalReference: d.client_id
  }
});

return [{ json: {
  client_id:       d.client_id,
  company:         d.company,
  email:           d.email,
  phone:           d.phone,
  document:        d.document,
  organization_id: d.organization_id,
  has_email:       d.has_email,
  proxy_body:      proxyBody
}}];

const d = $input.item.json;

const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('SUPABASE_URL ou SUPABASE_SERVICE_KEY não configurados nas env vars do n8n');
}

const proxyBody = {
  method: 'POST',
  path: '/v3/customers',
  payload: {
    name:              d.company,
    cpfCnpj:           d.document,
    email:             d.email,
    phone:             d.phone,
    externalReference: d.client_id
  }
};

const res = await $http.request({
  method: 'POST',
  url: `${supabaseUrl}/functions/v1/asaas-proxy`,
  headers: {
    'Authorization': `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json'
  },
  body: proxyBody,
  json: true
});

return [{ json: {
  ...d,
  asaas_response: res,
  asaas_id:  res?.id   || null,
  asaas_ok:  !!res?.id
}}];

const d = $input.item.json;

return [{ json: {
  client_id:       d.client_id,
  company:         d.company,
  email:           d.email,
  phone:           d.phone,
  organization_id: d.organization_id,
  has_email:       d.has_email,
  asaas_id:        d.asaas_id,
  asaas_ok:        d.asaas_ok
}}];

